import { useMemo, useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { api } from '../../lib/api.js';
import { Button } from '../../components/ui/button.jsx';
import { Input } from '../../components/ui/input.jsx';
import { Card } from '../../components/ui/card.jsx';
import { Select } from '../../components/ui/select.jsx';
import { Label } from '../../components/ui/label.jsx';
import { PageHeader } from '../../components/ui/page.jsx';
import { Badge } from '../../components/ui/badge.jsx';
import CRCSPermissionsConfig from './CRCSPermissionsConfig.jsx';

const ROLE_OPTIONS = [
  ['student', 'Student', 'Can maintain their profile, explore internships, apply, and upload reports.'],
  ['faculty', 'Faculty mentor', 'Can post research projects, guide assigned students, review reports, and enter marks.'],
  ['faculty_coordinator', 'Faculty coordinator', 'Can oversee assigned faculty and reassign research mentors when needed.'],
  ['hod', 'Head of department', 'Can view their department’s internship activity and progress.'],
  ['dean', 'Dean', 'Can view school-level internship progress.'],
  ['school_office', 'School office', 'Can view school-level mentor allocations and internship oversight information.'],
  ['crcs_coordinator', 'CRCS coordinator', 'Receives only the CRCS permissions selected by the Superadmin.'],
  ['crcs_superadmin', 'CRCS Superadmin', 'Has full CRCS administration access.'],
];

function StepTitle({ number, title, description }) {
  return <div className="mb-4 flex gap-3"><span className="grid h-7 w-7 shrink-0 place-items-center rounded-full bg-indigo-100 text-sm font-bold text-indigo-700">{number}</span><div><h2 className="font-bold text-slate-950">{title}</h2><p className="mt-0.5 text-sm leading-5 text-slate-600">{description}</p></div></div>;
}

function SchoolForm({ schools, onCreated }) {
  const [form, setForm] = useState({ name: '', code: '' });
  const [status, setStatus] = useState(null);
  const create = useMutation({ mutationFn: () => api('/schools', { method: 'POST', body: form }), onSuccess: () => { setStatus('School added. You can now add its departments.'); setForm({ name: '', code: '' }); onCreated(); }, onError: (error) => setStatus(error.message) });
  return <Card className="p-5"><h3 className="font-bold">Add a school</h3><p className="form-help mb-4">For example, “School of Engineering” with the code “SEAS”.</p><form className="space-y-3" onSubmit={(event) => { event.preventDefault(); create.mutate(); }}><div><Label>School name</Label><Input value={form.name} onChange={(event) => setForm((current) => ({ ...current, name: event.target.value }))} placeholder="School of Engineering" required /></div><div><Label>Short code</Label><Input value={form.code} onChange={(event) => setForm((current) => ({ ...current, code: event.target.value.toUpperCase() }))} placeholder="SEAS" required /></div>{status && <p className="text-sm text-slate-600">{status}</p>}<Button type="submit" disabled={create.isPending}>{create.isPending ? 'Adding…' : 'Add school'}</Button></form><div className="mt-5 border-t border-slate-100 pt-4"><p className="text-sm font-bold text-slate-900">Added schools ({schools.length})</p>{schools.length ? <ul className="mt-2 max-h-40 space-y-2 overflow-y-auto">{schools.map((school) => <li key={school.id} className="flex items-center justify-between gap-3 rounded-lg bg-slate-50 px-3 py-2 text-sm"><span className="font-medium text-slate-800">{school.name}</span><span className="rounded bg-indigo-100 px-2 py-0.5 text-xs font-bold text-indigo-800">{school.code}</span></li>)}</ul> : <p className="mt-2 text-sm text-slate-500">No schools have been added yet.</p>}</div></Card>;
}

function DepartmentForm({ schools, departments, onCreated }) {
  const [form, setForm] = useState({ name: '', code: '', school_id: '' });
  const [status, setStatus] = useState(null);
  const create = useMutation({ mutationFn: () => api('/departments', { method: 'POST', body: form }), onSuccess: () => { setStatus('Department added.'); setForm({ name: '', code: '', school_id: '' }); onCreated(); }, onError: (error) => setStatus(error.message) });
  return <Card className="p-5"><h3 className="font-bold">Add a department</h3><p className="form-help mb-4">A department belongs to one school and is used for faculty and student access.</p><form className="space-y-3" onSubmit={(event) => { event.preventDefault(); create.mutate(); }}><div><Label>School</Label><Select value={form.school_id} onChange={(event) => setForm((current) => ({ ...current, school_id: event.target.value }))} required><option value="">Choose a school</option>{schools.map((school) => <option key={school.id} value={school.id}>{school.name}</option>)}</Select></div><div><Label>Department name</Label><Input value={form.name} onChange={(event) => setForm((current) => ({ ...current, name: event.target.value }))} placeholder="Computer Science and Engineering" required /></div><div><Label>Short code</Label><Input value={form.code} onChange={(event) => setForm((current) => ({ ...current, code: event.target.value.toUpperCase() }))} placeholder="CSE" required /></div>{status && <p className="text-sm text-slate-600">{status}</p>}<Button type="submit" disabled={create.isPending || !schools.length}>{create.isPending ? 'Adding…' : 'Add department'}</Button></form><div className="mt-5 border-t border-slate-100 pt-4"><p className="text-sm font-bold text-slate-900">Added departments ({departments.length})</p>{departments.length ? <ul className="mt-2 max-h-40 space-y-2 overflow-y-auto">{departments.map((department) => <li key={department.id} className="rounded-lg bg-slate-50 px-3 py-2 text-sm"><p className="font-medium text-slate-800">{department.name} <span className="ml-1 rounded bg-indigo-100 px-2 py-0.5 text-xs font-bold text-indigo-800">{department.code}</span></p><p className="mt-0.5 text-xs text-slate-500">{schools.find((school) => school.id === department.school_id)?.name ?? 'School not found'}</p></li>)}</ul> : <p className="mt-2 text-sm text-slate-500">No departments have been added yet.</p>}</div></Card>;
}

export function BulkOnboard({ departments, onDone }) {
  const [file, setFile] = useState(null);
  const [results, setResults] = useState(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);
  async function submit(event) { event.preventDefault(); if (!file) return; setBusy(true); setError(null); try { const formData = new FormData(); formData.append('file', file); const data = await api('/admin/users/bulk', { method: 'POST', body: formData, isFormData: true }); setResults(data.results); onDone(data.results); } catch (failure) { setError(failure.message); } finally { setBusy(false); } }
  return <Card className="p-6"><StepTitle number="2" title="Add people from a spreadsheet" description="Best for a full class, department, school, or faculty list." /><div className="rounded-xl bg-indigo-50 p-4"><p className="text-sm font-bold text-indigo-950">Start with the Excel template</p><p className="mt-1 text-xs leading-5 text-indigo-800">It has a blank import sheet, safe examples for every supported role, and a field-reference sheet. Only the first sheet is imported.</p><a href="/templates/internship-portal-people-import-template.xlsx" download className="mt-3 inline-flex rounded-lg border border-indigo-300 bg-white px-3 py-2 text-sm font-bold text-indigo-700 hover:bg-indigo-100">Download Excel template</a></div><form className="mt-5" onSubmit={submit}><Label>Your completed spreadsheet</Label><input type="file" accept=".csv,text/csv,.xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" onChange={(event) => setFile(event.target.files?.[0] ?? null)} className="mt-2 block w-full rounded-lg border border-dashed border-slate-300 bg-slate-50 p-3 text-sm" /><p className="form-help">Upload a CSV or Excel (.xlsx) sheet with the template headers. Supported roles: <strong>student</strong>, <strong>faculty</strong>, <strong>faculty_coordinator</strong>, <strong>hod</strong>, <strong>dean</strong>, <strong>school_office</strong>, <strong>crcs_coordinator</strong>, and <strong>crcs_superadmin</strong>. Use matching organisation codes. Departments currently available: {departments.map((department) => department.code).join(', ') || 'add a department first'}.</p>{error && <p className="mt-3 text-sm text-red-600">{error}</p>}<Button type="submit" className="mt-4" disabled={!file || busy}>{busy ? 'Importing people…' : 'Import people'}</Button></form>{results && <div className="mt-5 rounded-xl border border-slate-200 p-4"><p className="font-bold text-slate-900">Import complete</p><p className="mt-1 text-sm text-slate-600">{results.filter((row) => row.ok).length} people added · {results.filter((row) => !row.ok).length} need attention</p>{results.some((row) => !row.ok) && <ul className="mt-3 list-disc space-y-1 pl-5 text-sm text-red-700">{results.filter((row) => !row.ok).map((row) => <li key={row.row}>Row {row.row}: {row.error}</li>)}</ul>}</div>}</Card>;
}

export function IndividualOnboard({ schools, departments, onDone }) {
  const [form, setForm] = useState({ email: '', password: '', full_name: '', phone: '', role: 'student', department_id: '', school_id: '', mentorship_scope: 'research' });
  const [status, setStatus] = useState(null);
  const needsDepartment = ['student', 'faculty', 'faculty_coordinator', 'hod'].includes(form.role);
  const needsSchool = ['dean', 'school_office'].includes(form.role);
  const role = ROLE_OPTIONS.find(([value]) => value === form.role);
  const create = useMutation({ mutationFn: () => api('/admin/users', { method: 'POST', body: { email: form.email, password: form.password, full_name: form.full_name, phone: form.phone || undefined, mentorship_scope: form.role === 'faculty' ? form.mentorship_scope : undefined, roles: [{ role: form.role, department_id: form.department_id || undefined, school_id: form.school_id || undefined }] } }), onSuccess: (user) => { setStatus(`${form.full_name} can now sign in.`); setForm({ email: '', password: '', full_name: '', phone: '', role: 'student', department_id: '', school_id: '', mentorship_scope: 'research' }); onDone(user); }, onError: (error) => setStatus(error.message) });
  return <Card className="p-6"><StepTitle number="2" title="Add one person" description="Best for a single account, replacement, or test user." /><form className="space-y-4" onSubmit={(event) => { event.preventDefault(); create.mutate(); }}><div className="grid gap-4 sm:grid-cols-2"><div><Label>Full name</Label><Input value={form.full_name} onChange={(event) => setForm((current) => ({ ...current, full_name: event.target.value }))} placeholder="Asha Kumar" required /></div><div><Label>Email address</Label><Input type="email" value={form.email} onChange={(event) => setForm((current) => ({ ...current, email: event.target.value }))} placeholder="asha@university.edu" required /></div></div><div className="grid gap-4 sm:grid-cols-2"><div><Label>Temporary password</Label><Input type="password" value={form.password} onChange={(event) => setForm((current) => ({ ...current, password: event.target.value }))} placeholder="At least 8 characters" minLength={8} required /></div><div><Label>Phone <span className="text-slate-400">(optional)</span></Label><Input value={form.phone} onChange={(event) => setForm((current) => ({ ...current, phone: event.target.value }))} placeholder="9876543210" /></div></div><div><Label>What will this person do?</Label><Select value={form.role} onChange={(event) => setForm((current) => ({ ...current, role: event.target.value, department_id: '', school_id: '' }))}>{ROLE_OPTIONS.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</Select><p className="form-help">{role?.[2]}</p></div>{form.role === 'faculty' && <div><Label>Mentor category</Label><Select value={form.mentorship_scope} onChange={(event) => setForm((current) => ({ ...current, mentorship_scope: event.target.value }))}><option value="research">Research internship mentor</option><option value="crcs_self">CRCS and self-internship mentor (maximum 5 students)</option></Select><p className="form-help">This controls the mentor’s dashboard and the internship students CRCS can allocate.</p></div>}{needsDepartment && <div><Label>Department</Label><Select value={form.department_id} onChange={(event) => setForm((current) => ({ ...current, department_id: event.target.value }))} required><option value="">Choose a department</option>{departments.map((department) => <option key={department.id} value={department.id}>{department.name}</option>)}</Select></div>}{needsSchool && <div><Label>School</Label><Select value={form.school_id} onChange={(event) => setForm((current) => ({ ...current, school_id: event.target.value }))} required><option value="">Choose a school</option>{schools.map((school) => <option key={school.id} value={school.id}>{school.name}</option>)}</Select></div>}{status && <p className={`text-sm ${create.isError ? 'text-red-600' : 'text-emerald-700'}`}>{status}</p>}<Button type="submit" disabled={create.isPending}>{create.isPending ? 'Creating account…' : 'Create account'}</Button></form></Card>;
}

const DIRECTORY_ROLES = [
  ['hod', 'Head of Department'],
  ['faculty_coordinator', 'Faculty Coordinators'],
  ['faculty', 'Faculty Mentors'],
  ['student', 'Students'],
  ['dean', 'Dean'],
  ['school_office', 'School Office'],
];

function LegacyPersonManagement({ person, initialTab = 'profile', onChanged, onClose }) {
  const [tab, setTab] = useState(initialTab);
  const [fullName, setFullName] = useState(person.full_name);
  const [phone, setPhone] = useState(person.phone ?? '');
  const [replacementId, setReplacementId] = useState('');
  const [message, setMessage] = useState(null);
  const { data: dependencies, isLoading: dependenciesLoading, error: dependenciesError } = useQuery({ queryKey: ['user-dependencies', person.id], queryFn: () => api(`/admin/users/${person.id}/dependencies`) });
  const update = useMutation({ mutationFn: () => api(`/admin/users/${person.id}`, { method: 'PATCH', body: { full_name: fullName.trim(), phone: phone.trim() || null } }), onSuccess: () => { setMessage('Profile updated.'); onChanged(); }, onError: (error) => setMessage(error.message) });
  const remove = useMutation({ mutationFn: () => api(`/admin/users/${person.id}/remove`, { method: 'POST', body: replacementId ? { replacement_user_id: replacementId } : {} }), onSuccess: (data) => { onChanged(); onClose(); }, onError: (error) => setMessage(error.message) });
  const mustReassign = dependencies?.requires_replacement;
  const canRemove = !dependenciesLoading && !dependenciesError && (!mustReassign || replacementId);
  return <div role="presentation" className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/45 p-4" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><Card role="dialog" aria-modal="true" aria-label="Manage portal user" className="max-h-[calc(100vh-2rem)] w-full max-w-2xl overflow-y-auto border-indigo-200 bg-white p-5 shadow-2xl"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-widest text-indigo-600">Manage person</p><h3 className="mt-1 text-lg font-bold text-slate-950">{person.full_name}</h3><p className="text-sm text-slate-600">{person.email}</p></div><Button type="button" variant="ghost" className="px-3 py-2" onClick={onClose}>Close</Button></div><div className="mt-5 flex gap-2 border-b border-indigo-100"><button type="button" className={`border-b-2 px-3 py-2 text-sm font-bold ${tab === 'profile' ? 'border-indigo-600 text-indigo-700' : 'border-transparent text-slate-600'}`} onClick={() => setTab('profile')}>Edit profile</button><button type="button" className={`border-b-2 px-3 py-2 text-sm font-bold ${tab === 'remove' ? 'border-red-500 text-red-700' : 'border-transparent text-slate-600'}`} onClick={() => setTab('remove')}>Remove access</button></div>{tab === 'profile' ? <form className="mt-5 grid gap-4 sm:grid-cols-2" onSubmit={(event) => { event.preventDefault(); setMessage(null); update.mutate(); }}><div><Label>Full name</Label><Input className="mt-2" value={fullName} onChange={(event) => setFullName(event.target.value)} required /></div><div><Label>Phone <span className="text-slate-400">(optional)</span></Label><Input className="mt-2" value={phone} onChange={(event) => setPhone(event.target.value)} placeholder="9876543210" /></div><div className="sm:col-span-2"><p className="form-help">Role and department assignments are retained here so existing records stay correct.</p>{message && <p className={`mt-2 text-sm ${update.isError ? 'text-red-700' : 'text-emerald-700'}`}>{message}</p>}<Button type="submit" className="mt-4" disabled={update.isPending || !fullName.trim()}>{update.isPending ? 'Saving…' : 'Save changes'}</Button></div></form> : <div className="mt-5"><div className="rounded-xl border border-amber-200 bg-amber-50 p-4"><p className="font-bold text-amber-950">Remove portal access safely</p><p className="mt-1 text-sm leading-5 text-amber-900">This disables sign-in but preserves records and history. If this person guides students or manages faculty, choose a replacement before continuing.</p></div>{dependenciesLoading && <p className="mt-4 text-sm text-slate-600">Checking people and assignments…</p>}{dependenciesError && <p className="mt-4 text-sm text-red-700">{dependenciesError.message}</p>}{dependencies && <div className="mt-4 space-y-4"><div className="grid gap-3 sm:grid-cols-2"><div className="rounded-lg bg-white p-3"><p className="text-xs font-bold uppercase tracking-wide text-slate-500">Active mentees</p><p className="mt-1 text-2xl font-bold text-slate-950">{dependencies.active_mentees}</p></div><div className="rounded-lg bg-white p-3"><p className="text-xs font-bold uppercase tracking-wide text-slate-500">Faculty managed</p><p className="mt-1 text-2xl font-bold text-slate-950">{dependencies.managed_faculty}</p></div></div>{mustReassign ? <div><Label>Move these relationships to</Label><Select className="mt-2" value={replacementId} onChange={(event) => setReplacementId(event.target.value)} required><option value="">Choose a replacement before removal</option>{dependencies.replacement_candidates.map((candidate) => <option key={candidate.id} value={candidate.id}>{candidate.full_name} — {candidate.email}</option>)}</Select>{!dependencies.replacement_candidates.length && <p className="mt-2 text-sm text-red-700">No eligible replacement is available. Add an appropriate Faculty Mentor or Faculty Coordinator first.</p>}<p className="form-help">The selected person receives all active mentees and/or faculty-coordinator relationships.</p></div> : <p className="text-sm text-slate-700">No active mentees or faculty relationships need to be moved.</p>}{message && <p className="text-sm text-red-700">{message}</p>}<Button type="button" variant="danger" onClick={() => { setMessage(null); remove.mutate(); }} disabled={!canRemove || remove.isPending}>{remove.isPending ? 'Removing…' : mustReassign ? 'Reassign and remove access' : 'Remove portal access'}</Button></div>}</div>}</Card></div>;
}

function PersonManagement({ person, schools, departments, initialTab = 'profile', onChanged, onClose }) {
  const assignment = person.roles?.find((item) => item.role === person.role && item.department_id === person.department?.id) ?? { role: person.role, department_id: person.department?.id ?? null, school_id: person.school_id ?? null };
  const otherRoles = (person.roles ?? []).filter((item) => !(item.role === assignment.role && item.department_id === assignment.department_id && item.school_id === assignment.school_id));
  const [tab, setTab] = useState(initialTab);
  const [form, setForm] = useState({ full_name: person.full_name, email: person.email, phone: person.phone ?? '', password: '', role: assignment.role, department_id: assignment.department_id ?? '', school_id: assignment.school_id ?? '', mentorship_scope: person.mentorship_scope ?? 'research' });
  const [replacementId, setReplacementId] = useState('');
  const [message, setMessage] = useState(null);
  const needsDepartment = ['student', 'faculty', 'faculty_coordinator', 'hod'].includes(form.role);
  const needsSchool = ['dean', 'school_office'].includes(form.role);
  const roleInfo = ROLE_OPTIONS.find(([value]) => value === form.role);
  const { data: dependencies, isLoading: dependenciesLoading, error: dependenciesError } = useQuery({ queryKey: ['user-dependencies', person.id], queryFn: () => api(`/admin/users/${person.id}/dependencies`) });
  const update = useMutation({
    mutationFn: () => api(`/admin/users/${person.id}`, { method: 'PATCH', body: {
      full_name: form.full_name.trim(), email: form.email.trim(), phone: form.phone.trim() || null, password: form.password || undefined,
      mentorship_scope: form.role === 'faculty' ? form.mentorship_scope : undefined,
      roles: [...otherRoles, { role: form.role, department_id: needsDepartment ? form.department_id : undefined, school_id: needsSchool ? form.school_id : undefined }],
    } }),
    onSuccess: () => { setForm((current) => ({ ...current, password: '' })); setMessage('Account details and access assignment updated.'); onChanged(); },
    onError: (error) => setMessage(error.message),
  });
  const remove = useMutation({ mutationFn: () => api(`/admin/users/${person.id}/remove`, { method: 'POST', body: replacementId ? { replacement_user_id: replacementId } : {} }), onSuccess: () => { onChanged(); onClose(); }, onError: (error) => setMessage(error.message) });
  const mustReassign = dependencies?.requires_replacement;
  const canRemove = !dependenciesLoading && !dependenciesError && (!mustReassign || replacementId);
  const change = (field) => (event) => setForm((current) => ({ ...current, [field]: event.target.value }));
  return <div role="presentation" className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/45 p-4" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><Card role="dialog" aria-modal="true" aria-label="Manage portal user" className="max-h-[calc(100vh-2rem)] w-full max-w-2xl overflow-y-auto border-indigo-200 bg-white p-5 shadow-2xl"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-widest text-indigo-600">Manage person</p><h3 className="mt-1 text-lg font-bold text-slate-950">{person.full_name}</h3><p className="text-sm text-slate-600">{person.email}</p></div><Button type="button" variant="ghost" className="px-3 py-2" onClick={onClose}>Close</Button></div><div className="mt-5 flex gap-2 border-b border-indigo-100"><button type="button" className={`border-b-2 px-3 py-2 text-sm font-bold ${tab === 'profile' ? 'border-indigo-600 text-indigo-700' : 'border-transparent text-slate-600'}`} onClick={() => setTab('profile')}>Edit profile</button><button type="button" className={`border-b-2 px-3 py-2 text-sm font-bold ${tab === 'remove' ? 'border-red-500 text-red-700' : 'border-transparent text-slate-600'}`} onClick={() => setTab('remove')}>Remove access</button></div>{tab === 'profile' ? <form className="mt-5 grid gap-4 sm:grid-cols-2" onSubmit={(event) => { event.preventDefault(); setMessage(null); update.mutate(); }}><div><Label>Full name</Label><Input className="mt-2" value={form.full_name} onChange={change('full_name')} required /></div><div><Label>Email address</Label><Input className="mt-2" type="email" value={form.email} onChange={change('email')} required /></div><div><Label>New temporary password <span className="text-slate-400">(optional)</span></Label><Input className="mt-2" type="password" value={form.password} onChange={change('password')} placeholder="Leave blank to keep current password" minLength={8} /></div><div><Label>Phone <span className="text-slate-400">(optional)</span></Label><Input className="mt-2" value={form.phone} onChange={change('phone')} placeholder="9876543210" /></div><div className="sm:col-span-2"><Label>What will this person do?</Label><Select className="mt-2" value={form.role} onChange={(event) => setForm((current) => ({ ...current, role: event.target.value, department_id: '', school_id: '' }))}>{ROLE_OPTIONS.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</Select><p className="form-help">{roleInfo?.[2]}</p></div>{form.role === 'faculty' && <div className="sm:col-span-2"><Label>Mentor category</Label><Select className="mt-2" value={form.mentorship_scope} onChange={change('mentorship_scope')}><option value="research">Research internship mentor</option><option value="crcs_self">CRCS and self-internship mentor (maximum 5 students)</option></Select></div>}{needsDepartment && <div className="sm:col-span-2"><Label>Department</Label><Select className="mt-2" value={form.department_id} onChange={change('department_id')} required><option value="">Choose a department</option>{departments.map((department) => <option key={department.id} value={department.id}>{department.name}</option>)}</Select></div>}{needsSchool && <div className="sm:col-span-2"><Label>School</Label><Select className="mt-2" value={form.school_id} onChange={change('school_id')} required><option value="">Choose a school</option>{schools.map((school) => <option key={school.id} value={school.id}>{school.name}</option>)}</Select></div>}<div className="sm:col-span-2"><p className="form-help">This changes the selected role assignment while preserving any other roles this person already has.</p>{message && <p className={`mt-2 text-sm ${update.isError ? 'text-red-700' : 'text-emerald-700'}`}>{message}</p>}<Button type="submit" className="mt-4" disabled={update.isPending || !form.full_name.trim() || !form.email.trim() || (needsDepartment && !form.department_id) || (needsSchool && !form.school_id)}>{update.isPending ? 'Saving…' : 'Save changes'}</Button></div></form> : <div className="mt-5"><div className="rounded-xl border border-amber-200 bg-amber-50 p-4"><p className="font-bold text-amber-950">Remove portal access safely</p><p className="mt-1 text-sm leading-5 text-amber-900">This disables sign-in but preserves records and history. If this person guides students or manages faculty, choose a replacement before continuing.</p></div>{dependenciesLoading && <p className="mt-4 text-sm text-slate-600">Checking people and assignments…</p>}{dependenciesError && <p className="mt-4 text-sm text-red-700">{dependenciesError.message}</p>}{dependencies && <div className="mt-4 space-y-4"><div className="grid gap-3 sm:grid-cols-2"><div className="rounded-lg bg-white p-3"><p className="text-xs font-bold uppercase tracking-wide text-slate-500">Active mentees</p><p className="mt-1 text-2xl font-bold text-slate-950">{dependencies.active_mentees}</p></div><div className="rounded-lg bg-white p-3"><p className="text-xs font-bold uppercase tracking-wide text-slate-500">Faculty managed</p><p className="mt-1 text-2xl font-bold text-slate-950">{dependencies.managed_faculty}</p></div></div>{mustReassign ? <div><Label>Move these relationships to</Label><Select className="mt-2" value={replacementId} onChange={(event) => setReplacementId(event.target.value)} required><option value="">Choose a replacement before removal</option>{dependencies.replacement_candidates.map((candidate) => <option key={candidate.id} value={candidate.id}>{candidate.full_name} — {candidate.email}</option>)}</Select>{!dependencies.replacement_candidates.length && <p className="mt-2 text-sm text-red-700">No eligible replacement is available. Add an appropriate Faculty Mentor or Faculty Coordinator first.</p>}<p className="form-help">The selected person receives all active mentees and/or faculty-coordinator relationships.</p></div> : <p className="text-sm text-slate-700">No active mentees or faculty relationships need to be moved.</p>}{message && <p className="text-sm text-red-700">{message}</p>}<Button type="button" variant="danger" onClick={() => { setMessage(null); remove.mutate(); }} disabled={!canRemove || remove.isPending}>{remove.isPending ? 'Removing…' : mustReassign ? 'Reassign and remove access' : 'Remove portal access'}</Button></div>}</div>}</Card></div>;
}

const TRACK_LABELS = { research: 'Research internship', crcs_opportunity: 'CRCS opportunity', self_internship: 'Self-internship' };
const REPORT_LABELS = { weekly: 'Weekly report', midterm: 'Mid-term report', synopsis: 'Synopsis', final: 'Final report' };

function applicationStatus(record) {
  const status = record?.internship?.status;
  const labels = {
    applied: ['Waiting for approval', 'CRCS decision needed', 'pending'],
    pending_crcs_approval: ['Waiting for approval', 'CRCS decision needed', 'pending'],
    pending_faculty: ['Waiting for faculty', 'Faculty decision needed', 'pending'],
    under_review: ['Under review', 'Application is being reviewed', 'pending'],
    offered: ['Offer received', 'Awaiting final CRCS approval', 'pending'],
    crcs_approved: ['Approved', 'CRCS approved', 'approved'],
    active: ['Active internship', 'CRCS approved · internship in progress', 'approved'],
    rejected: ['Rejected', 'Application was not approved', 'rejected'],
    revoked: ['Closed', 'Application is no longer active', 'revoked'],
  };
  if (labels[status]) return { label: labels[status][0], detail: labels[status][1], tone: labels[status][2] };
  if (record?.preference) return { label: 'No application yet', detail: 'Preference saved, but no application was submitted', tone: 'default' };
  return { label: 'No preference selected', detail: 'Student has not chosen an internship pathway', tone: 'default' };
}

function StudentApplicationDialog({ record, onClose }) {
  const application = applicationStatus(record);
  const documents = record.documents ?? [];
  const organisation = record.organisation ?? {};
  const hierarchy = [['School', organisation.school?.name], ['Dean', organisation.dean?.full_name], ['Department', organisation.department?.name], ['HOD', organisation.hod?.full_name], ['Faculty mentor', organisation.faculty_mentor?.full_name], ['Faculty Coordinator', organisation.faculty_coordinator?.full_name]];
  return <div role="presentation" className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/45 p-4" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><Card role="dialog" aria-modal="true" aria-label={`Internship overview for ${record.student.full_name}`} className="max-h-[calc(100vh-2rem)] w-full max-w-2xl overflow-y-auto border-indigo-200 bg-white p-5 shadow-2xl"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-widest text-indigo-600">Student internship overview</p><h3 className="mt-1 text-lg font-bold text-slate-950">{record.student.full_name}</h3><p className="text-sm text-slate-600">{record.profile?.roll_number ?? 'No roll number'} · {record.student.email}</p></div><Button type="button" variant="ghost" className="px-3 py-2" onClick={onClose}>Close</Button></div><div className="mt-5 grid gap-3 sm:grid-cols-2"><div className="rounded-xl bg-slate-50 p-4"><p className="text-xs font-bold uppercase tracking-wide text-slate-500">Internship pathway</p><p className="mt-1 font-bold text-slate-900">{TRACK_LABELS[record.internship?.path] ?? TRACK_LABELS[record.preference?.track] ?? 'Not selected'}</p><p className="mt-1 text-sm text-slate-600">{record.internship?.title ?? 'No application submitted'}</p></div><div className="rounded-xl bg-slate-50 p-4"><p className="text-xs font-bold uppercase tracking-wide text-slate-500">Approval status</p><div className="mt-1"><Badge status={application.tone}>{application.label}</Badge></div><p className="mt-1 text-sm text-slate-600">{application.detail}</p></div></div><div className="mt-5"><p className="text-sm font-bold text-slate-900">Organisation and supervision</p><div className="mt-2 grid gap-2 sm:grid-cols-2">{hierarchy.map(([label, value]) => <div key={label} className="rounded-lg border border-slate-200 p-3"><p className="text-xs font-bold uppercase tracking-wide text-slate-500">{label}</p><p className="mt-1 text-sm font-semibold text-slate-800">{value ?? 'Not assigned yet'}</p></div>)}</div></div><div className="mt-5"><p className="text-sm font-bold text-slate-900">Report progress</p><div className="mt-2 grid gap-2 sm:grid-cols-2">{Object.entries(REPORT_LABELS).map(([key, label]) => { const report = record.reports?.[key]; const submitted = report?.state === 'submitted'; return <div key={key} className="rounded-lg border border-slate-200 p-3"><div className="flex items-center justify-between gap-2"><p className="text-sm font-semibold text-slate-800">{label}</p><Badge status={submitted ? 'approved' : report?.state === 'waiting' ? 'pending' : 'default'}>{submitted ? `${report.count} submitted` : report?.state === 'waiting' ? 'Waiting' : 'Locked'}</Badge></div>{submitted && <div className="mt-2 space-y-1">{report.files?.map((file) => file.url ? <a key={file.id} href={file.url} target="_blank" rel="noreferrer" className="block truncate text-xs font-medium text-indigo-700 hover:underline">{file.file_name} ↗</a> : <p key={file.id} className="truncate text-xs text-slate-600">{file.file_name}</p>)}</div>} {!submitted && <p className="mt-1 text-xs text-slate-500">{report?.label ?? 'Not submitted'}</p>}</div>; })}</div></div><div className="mt-5"><div className="flex items-center justify-between gap-3"><p className="text-sm font-bold text-slate-900">Uploaded documents</p><Badge status={documents.length ? 'approved' : 'default'}>{documents.length} file{documents.length === 1 ? '' : 's'}</Badge></div>{documents.length ? <ul className="mt-2 space-y-2">{documents.map((document) => <li key={document.id} className="rounded-lg border border-slate-200 px-3 py-2 text-sm">{document.url ? <a href={document.url} target="_blank" rel="noreferrer" className="font-medium text-indigo-700 hover:underline">{document.file_name} ↗</a> : <span className="font-medium text-slate-800">{document.file_name}</span>}<p className="mt-0.5 text-xs text-slate-500">{document.related_entity_type?.replaceAll('_', ' ') ?? 'Document'} · {document.review_status?.replaceAll('_', ' ') ?? 'Pending review'}</p></li>)}</ul> : <p className="mt-2 text-sm text-slate-500">No documents uploaded yet.</p>}</div><a href="/crcs/student-records" className="mt-5 inline-flex rounded-lg border border-indigo-200 bg-white px-3 py-2 text-sm font-bold text-indigo-700 hover:bg-indigo-50">Open full student records</a></Card></div>;
}

function OrganisationPersonDialog({ person, onClose }) {
  const { data, isLoading, error } = useQuery({ queryKey: ['person-organisation', person.id, person.role], queryFn: () => api(`/admin/users/${person.id}/organisation?role=${encodeURIComponent(person.role)}`) });
  const organisation = data?.organisation ?? {};
  const roleLabel = ROLE_OPTIONS.find(([value]) => value === person.role)?.[1] ?? person.role.replaceAll('_', ' ');
  const isSchoolOverview = ['dean', 'school_office'].includes(person.role);
  const hierarchy = [
    ['School', organisation.school?.name], ['Dean', organisation.dean?.full_name],
    ...(!isSchoolOverview ? [['Department', organisation.department?.name], ['HOD', organisation.hod?.full_name]] : []),
    ...(person.role === 'faculty' ? [['Faculty mentor', organisation.faculty_mentor?.full_name], ['Faculty Coordinator', organisation.faculty_coordinator?.full_name]] : []),
    ...(person.role === 'faculty_coordinator' ? [['Faculty Coordinator', organisation.faculty_coordinator?.full_name]] : []),
  ];
  return (
    <div role="presentation" className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/45 p-4" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}>
      <Card role="dialog" aria-modal="true" aria-label={`Organisation overview for ${person.full_name}`} className="max-h-[calc(100vh-2rem)] w-full max-w-2xl overflow-y-auto border-indigo-200 bg-white p-5 shadow-2xl">
        <div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-widest text-indigo-600">Organisation overview</p><h3 className="mt-1 text-lg font-bold text-slate-950">{person.full_name}</h3><p className="text-sm text-slate-600">{roleLabel} · {person.email}</p></div><Button type="button" variant="ghost" className="px-3 py-2" onClick={onClose}>Close</Button></div>
        {isLoading && <p className="mt-5 text-sm text-slate-600">Loading organisation relationships…</p>}
        {error && <p className="mt-5 text-sm text-red-700">{error.message}</p>}
        {data && <><div className="mt-5"><p className="text-sm font-bold text-slate-900">Organisation</p><div className="mt-2 grid gap-2 sm:grid-cols-2">{hierarchy.map(([label, value]) => <div key={label} className="rounded-lg border border-slate-200 p-3"><p className="text-xs font-bold uppercase tracking-wide text-slate-500">{label}</p><p className="mt-1 text-sm font-semibold text-slate-800">{value ?? 'Not assigned yet'}</p></div>)}</div></div>
          {isSchoolOverview && <DepartmentShortcuts departments={organisation.departments} />}
          {isSchoolOverview && <OrganisationHierarchy departments={organisation.hierarchy} />}
          {person.role === 'faculty' && <div className="mt-5 rounded-xl bg-slate-50 p-4"><p className="text-sm font-bold text-slate-900">Mentor category</p><p className="mt-1 text-sm text-slate-600">{data.person.mentorship_scope === 'crcs_self' ? 'CRCS and self-internship mentor' : 'Research internship mentor'}</p></div>}
          {person.role === 'faculty' && <OrganisationPeopleList title="Students assigned to this Faculty Mentor" people={organisation.assigned_students} empty="No students are currently assigned to this Faculty Mentor." />}
          {person.role === 'faculty_coordinator' && <OrganisationPeopleList title="Faculty mentors mapped to this coordinator" people={organisation.assigned_faculty} empty="No faculty mentors are mapped yet." />}
          {['hod', 'faculty_coordinator'].includes(person.role) && <OrganisationPeopleList title="Faculty mentors in this department" people={organisation.faculty_mentors} empty="No faculty mentors are assigned to this department." />}
          {person.role === 'hod' && <OrganisationPeopleList title="Faculty Coordinators mapped to this HOD's department" people={organisation.faculty_coordinators} empty="No Faculty Coordinators are assigned to this department yet." />}
        </>}
      </Card>
    </div>
  );
}

function OrganisationPeopleList({ title, people = [], empty }) {
  return <div className="mt-5"><p className="text-sm font-bold text-slate-900">{title}</p>{people.length ? <div className="mt-2 grid gap-2 sm:grid-cols-2">{people.map((member) => <div key={member.id} className="rounded-lg border border-slate-200 p-3"><p className="text-sm font-semibold text-slate-800">{member.full_name}</p><p className="truncate text-xs text-slate-500">{member.email}</p>{member.pathway && <p className="mt-1 text-xs font-medium text-indigo-700">{member.pathway} · {member.status?.replaceAll('_', ' ')}</p>}</div>)}</div> : <p className="mt-2 text-sm text-slate-500">{empty}</p>}</div>;
}

function DepartmentShortcuts({ departments = [] }) {
  return <div className="mt-5"><p className="text-sm font-bold text-slate-900">Departments in this school</p>{departments.length ? <div className="mt-2 grid gap-2 sm:grid-cols-2">{departments.map((department) => <div key={department.id} className="rounded-lg border border-slate-200 p-3"><p className="text-xs font-bold uppercase tracking-wide text-slate-500">Department</p><div className="mt-1 flex items-start justify-between gap-2"><p className="text-sm font-semibold text-slate-800">{department.name}</p><span className="shrink-0 rounded bg-indigo-50 px-2 py-0.5 text-xs font-bold text-indigo-700">{department.code}</span></div></div>)}</div> : <p className="mt-2 text-sm text-slate-500">No departments are linked to this school yet.</p>}</div>;
}

function OrganisationHierarchy({ departments = [] }) {
  return <div className="mt-5"><p className="text-sm font-bold text-slate-900">School hierarchy</p><p className="mt-1 text-sm text-slate-600">Dean → department HOD → Faculty Coordinator → Faculty Mentor → assigned students.</p>{departments.length ? <div className="mt-3 space-y-3">{departments.map((department) => <details key={department.id} className="rounded-xl border border-slate-200 bg-slate-50 p-4"><summary className="cursor-pointer list-none"><p className="font-bold text-slate-900">{department.name} <span className="font-normal text-slate-500">({department.code})</span></p><p className="mt-1 text-sm text-slate-600">HOD: {department.hod?.full_name ?? 'Not assigned yet'}</p></summary><div className="mt-4 space-y-3 border-t border-slate-200 pt-3">{department.coordinators?.map((coordinator) => <div key={coordinator.id} className="rounded-lg border border-indigo-100 bg-white p-3"><p className="text-sm font-bold text-indigo-950">Faculty Coordinator: {coordinator.full_name}</p><p className="text-xs text-slate-500">{coordinator.email}</p>{coordinator.faculty?.length ? <div className="mt-3 space-y-2">{coordinator.faculty.map((faculty) => <div key={faculty.id} className="rounded-md bg-slate-50 p-3"><p className="text-sm font-semibold text-slate-800">Faculty Mentor: {faculty.full_name}</p><p className="text-xs text-slate-500">{faculty.email}</p><p className="mt-2 text-xs font-bold uppercase tracking-wide text-slate-500">Students ({faculty.students?.length ?? 0})</p>{faculty.students?.length ? <ul className="mt-1 space-y-1 text-sm text-slate-700">{faculty.students.map((student) => <li key={student.id}>{student.full_name} <span className="text-xs text-slate-500">· {student.pathway}</span></li>)}</ul> : <p className="mt-1 text-xs text-slate-500">No students assigned yet.</p>}</div>)}</div> : <p className="mt-2 text-sm text-slate-500">No faculty mentors are mapped to this coordinator yet.</p>}</div>)}{department.unmapped_faculty?.length ? <div className="rounded-lg border border-amber-200 bg-amber-50 p-3"><p className="text-sm font-bold text-amber-950">Faculty mentors awaiting a Coordinator mapping</p>{department.unmapped_faculty.map((faculty) => <p key={faculty.id} className="mt-1 text-sm text-amber-900">{faculty.full_name} · {faculty.students?.length ?? 0} assigned student(s)</p>)}</div> : null}{department.unassigned_students?.length ? <div className="rounded-lg border border-slate-200 bg-white p-3"><p className="text-sm font-bold text-slate-800">Students awaiting Faculty Mentor allocation</p><p className="mt-1 text-sm text-slate-600">{department.unassigned_students.map((student) => student.full_name).join(', ')}</p></div> : null}</div></details>)}</div> : <p className="mt-2 text-sm text-slate-500">No departments are linked to this school yet.</p>}</div>;
}

function PersonList({ title, people, onEdit, onDelete, studentRecordsById, onViewStudent, onViewOrganisation }) {
  if (!people.length) return null;
  return <div className="border-t border-slate-100 px-5 py-4 first:border-t-0"><div className="mb-3 flex items-center justify-between"><p className="text-sm font-bold text-slate-800">{title}</p><span className="rounded-full bg-slate-100 px-2 py-0.5 text-xs font-bold text-slate-600">{people.length}</span></div><div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{people.map((person) => { const record = person.role === 'student' ? studentRecordsById?.[person.id] : null; const application = record ? applicationStatus(record) : null; const canOpen = Boolean(record) || person.role !== 'student'; const openPerson = () => { if (record) onViewStudent(record); else if (person.role !== 'student') onViewOrganisation(person); }; return <div key={`${person.id}-${person.role}`} role={canOpen ? 'button' : undefined} tabIndex={canOpen ? 0 : undefined} onClick={openPerson} onKeyDown={(event) => { if (canOpen && (event.key === 'Enter' || event.key === ' ')) { event.preventDefault(); openPerson(); } }} className={`rounded-lg bg-slate-50 px-3 py-3 ${canOpen ? 'cursor-pointer ring-1 ring-transparent hover:bg-indigo-50 hover:ring-indigo-200 focus:outline-none focus:ring-2 focus:ring-indigo-500' : ''}`}><p className="truncate text-sm font-semibold text-slate-900">{person.full_name}</p><p className="truncate text-xs text-slate-500">{person.email}</p>{record && <div className="mt-3 rounded-lg border border-slate-200 bg-white p-2.5"><div className="flex flex-wrap items-center justify-between gap-2"><p className="text-xs font-bold uppercase tracking-wide text-slate-500">Application</p><Badge status={application.tone}>{application.label}</Badge></div><p className="mt-1 truncate text-xs font-medium text-slate-700">{TRACK_LABELS[record.internship?.path] ?? TRACK_LABELS[record.preference?.track] ?? 'No pathway selected'}</p><p className="mt-0.5 text-xs text-slate-500">{application.detail}</p><span className="mt-2 block text-xs font-bold text-indigo-700">Click to view full student record</span></div>}{person.role !== 'student' && <span className="mt-3 block text-xs font-bold text-indigo-700">Click to view organisation</span>}<div className="mt-3 flex gap-2"><button type="button" onClick={(event) => { event.stopPropagation(); onEdit(person); }} className="rounded-md bg-white px-2.5 py-1.5 text-xs font-bold text-indigo-700 shadow-sm ring-1 ring-inset ring-indigo-200 hover:bg-indigo-50">Edit</button><button type="button" onClick={(event) => { event.stopPropagation(); onDelete(person); }} className="rounded-md bg-white px-2.5 py-1.5 text-xs font-bold text-red-700 shadow-sm ring-1 ring-inset ring-red-200 hover:bg-red-50">Delete</button></div></div>; })}</div></div>;
}

export function PeopleDirectory({ users, schools, departments, studentRecords = [], cycleParticipantTypes = null, onChanged, showHeading = true }) {
  const [schoolId, setSchoolId] = useState('');
  const [departmentId, setDepartmentId] = useState('');
  const [role, setRole] = useState('');
  const [search, setSearch] = useState('');
  const [selectedPerson, setSelectedPerson] = useState(null);
  const [selectedStudentRecord, setSelectedStudentRecord] = useState(null);
  const [selectedOrganisationPerson, setSelectedOrganisationPerson] = useState(null);
  const departmentsById = Object.fromEntries(departments.map((department) => [department.id, department]));
  const studentRecordsById = useMemo(() => Object.fromEntries(studentRecords.map((record) => [record.student.id, record])), [studentRecords]);
  const selectedDepartments = schoolId ? departments.filter((department) => department.school_id === schoolId) : departments;
  const rows = useMemo(() => users.filter((user) => user.is_active !== false).flatMap((user) => (user.roles ?? []).filter((assignment) => !cycleParticipantTypes || cycleParticipantTypes.get(user.id) === assignment.role).map((assignment) => {
    const department = departmentsById[assignment.department_id];
    return { ...user, role: assignment.role, department, school_id: assignment.school_id ?? department?.school_id ?? null };
  })).filter((row) => (!schoolId || row.school_id === schoolId) && (!departmentId || row.department?.id === departmentId) && (!role || row.role === role) && (!search.trim() || `${row.full_name} ${row.email}`.toLowerCase().includes(search.toLowerCase()))), [users, departments, cycleParticipantTypes, schoolId, departmentId, role, search]);
  const groupedSchools = schools.map((school) => ({ school, departments: departments.filter((department) => department.school_id === school.id) })).filter(({ school }) => !schoolId || school.id === schoolId);
  const clear = () => { setSchoolId(''); setDepartmentId(''); setRole(''); setSearch(''); };
  const openPerson = (person, manageTab) => setSelectedPerson({ ...person, manageTab });
  const personActions = { onEdit: (person) => openPerson(person, 'profile'), onDelete: (person) => openPerson(person, 'remove'), studentRecordsById, onViewStudent: setSelectedStudentRecord, onViewOrganisation: setSelectedOrganisationPerson };
  return <section className={showHeading ? 'mt-10' : ''}>
    {showHeading && <div className="mb-5"><h2 className="section-title">All people</h2><p className="mt-1 text-sm text-slate-600">Open a school, then a department, to see HOD, Faculty Coordinators, Faculty Mentors, and Students in order. Click any faculty or oversight role to view its organisation relationship.</p></div>}
    {selectedPerson && <PersonManagement key={`${selectedPerson.id}-${selectedPerson.manageTab}`} person={selectedPerson} schools={schools} departments={departments} initialTab={selectedPerson.manageTab} onChanged={onChanged} onClose={() => setSelectedPerson(null)} />}
    {selectedStudentRecord && <StudentApplicationDialog record={selectedStudentRecord} onClose={() => setSelectedStudentRecord(null)} />}
    {selectedOrganisationPerson && <OrganisationPersonDialog person={selectedOrganisationPerson} onClose={() => setSelectedOrganisationPerson(null)} />}
    <Card className="p-5"><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><div><Label>Search</Label><Input className="mt-2" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Name or email" /></div><div><Label>School</Label><Select className="mt-2" value={schoolId} onChange={(event) => { setSchoolId(event.target.value); setDepartmentId(''); }}><option value="">All schools</option>{schools.map((school) => <option key={school.id} value={school.id}>{school.name}</option>)}</Select></div><div><Label>Department</Label><Select className="mt-2" value={departmentId} onChange={(event) => setDepartmentId(event.target.value)}><option value="">All departments</option>{selectedDepartments.map((department) => <option key={department.id} value={department.id}>{department.name}</option>)}</Select></div><div><Label>Role</Label><Select className="mt-2" value={role} onChange={(event) => setRole(event.target.value)}><option value="">All roles</option>{DIRECTORY_ROLES.map(([value, label]) => <option key={value} value={value}>{label}</option>)}<option value="crcs_coordinator">CRCS Coordinator</option><option value="crcs_superadmin">CRCS Superadmin</option></Select></div></div><div className="mt-4 flex items-center justify-between"><p className="text-sm text-slate-600"><span className="font-bold text-slate-900">{rows.length}</span> matching role assignment{rows.length === 1 ? '' : 's'}</p><button type="button" onClick={clear} className="text-sm font-bold text-indigo-700 hover:underline">Clear filters</button></div></Card>
    <div className="mt-5 space-y-4">{groupedSchools.map(({ school, departments: schoolDepartments }) => { const schoolRows = rows.filter((row) => row.school_id === school.id); return <details key={school.id} open={!!schoolId} className="portal-card group"><summary className="flex cursor-pointer list-none items-center justify-between gap-4 p-5"><div><p className="text-lg font-bold text-slate-950">{school.name}</p><p className="mt-1 text-sm text-slate-600">{schoolRows.length} people in this school</p></div><span className="text-sm font-bold text-indigo-700 group-open:hidden">Open ▼</span><span className="hidden text-sm font-bold text-indigo-700 group-open:inline">Close ▲</span></summary><div className="border-t border-slate-200 bg-slate-50 p-4 space-y-3">{schoolRows.filter((row) => row.role === 'dean').length > 0 && <Card className="overflow-hidden"><PersonList title="Dean" people={schoolRows.filter((row) => row.role === 'dean')} {...personActions} /></Card>}{schoolDepartments.filter((department) => !departmentId || department.id === departmentId).map((department) => { const departmentRows = schoolRows.filter((row) => row.department?.id === department.id); return <details key={department.id} open={!!departmentId} className="rounded-xl border border-slate-200 bg-white"><summary className="flex cursor-pointer list-none items-center justify-between gap-3 p-4"><div><p className="font-bold text-slate-900">{department.name}</p><p className="text-sm text-slate-600">{departmentRows.length} people</p></div><span className="text-sm font-bold text-indigo-700">View ▼</span></summary><div className="border-t border-slate-200">{DIRECTORY_ROLES.filter(([value]) => value !== 'dean').map(([value, label]) => <PersonList key={value} title={label} people={departmentRows.filter((row) => row.role === value)} {...personActions} />)}{!departmentRows.length && <p className="p-4 text-sm text-slate-500">No people match the selected filters.</p>}</div></details>; })}{!schoolRows.length && <p className="p-4 text-sm text-slate-500">No people match the selected filters in this school.</p>}</div></details>; })}<details className="portal-card group"><summary className="flex cursor-pointer list-none items-center justify-between gap-4 p-5"><div><p className="text-lg font-bold text-slate-950">CRCS team</p><p className="mt-1 text-sm text-slate-600">Superadmin and CRCS Coordinator accounts</p></div><span className="text-sm font-bold text-indigo-700">Open ▼</span></summary><div className="border-t border-slate-200"><PersonList title="CRCS Superadmin" people={rows.filter((row) => row.role === 'crcs_superadmin')} {...personActions} /><PersonList title="CRCS Coordinators" people={rows.filter((row) => row.role === 'crcs_coordinator')} {...personActions} /></div></details></div>
  </section>;
}

export function FacultyCoordinatorMapping() {
  const queryClient = useQueryClient();
  const [coordinatorId, setCoordinatorId] = useState('');
  const [facultyIds, setFacultyIds] = useState([]);
  const [facultySearch, setFacultySearch] = useState('');
  const [message, setMessage] = useState(null);
  const { data, isLoading, error } = useQuery({ queryKey: ['faculty-coordinator-mapping'], queryFn: () => api('/admin/faculty-coordinator-mapping') });
  const coordinators = data?.coordinators ?? [];
  const selectedCoordinator = coordinators.find((item) => item.id === coordinatorId);
  const capacity = Math.max(0, 10 - (selectedCoordinator?.assigned_faculty?.length ?? 0));
  const availableFaculty = (data?.unassigned_faculty ?? []).filter((faculty) => faculty.department_id === selectedCoordinator?.department_id);
  const filteredFaculty = availableFaculty.filter((faculty) => faculty.full_name.toLowerCase().includes(facultySearch.trim().toLowerCase()) || faculty.email?.toLowerCase().includes(facultySearch.trim().toLowerCase()));
  const refresh = () => { queryClient.invalidateQueries({ queryKey: ['faculty-coordinator-mapping'] }); queryClient.invalidateQueries({ queryKey: ['portal-users'] }); };
  const mapFaculty = useMutation({ mutationFn: () => api('/admin/faculty-coordinator-mapping', { method: 'POST', body: { coordinator_id: coordinatorId, faculty_ids: facultyIds } }), onSuccess: () => { setMessage(`${facultyIds.length} faculty member(s) mapped.`); setFacultyIds([]); refresh(); }, onError: (failure) => setMessage(failure.message) });
  const unmapFaculty = useMutation({ mutationFn: (facultyId) => api(`/admin/faculty-coordinator-mapping/${facultyId}`, { method: 'DELETE' }), onSuccess: () => { setMessage('Faculty mapping removed.'); refresh(); }, onError: (failure) => setMessage(failure.message) });
  const toggleFaculty = (facultyId) => setFacultyIds((current) => current.includes(facultyId) ? current.filter((id) => id !== facultyId) : current.length < capacity ? [...current, facultyId] : current);
  const selectAllVisible = () => setFacultyIds((current) => {
    const next = [...current];
    filteredFaculty.forEach((faculty) => { if (!next.includes(faculty.id) && next.length < capacity) next.push(faculty.id); });
    return next;
  });
  return <Card className="p-5"><h3 className="font-bold">Map Faculty Coordinator</h3><p className="form-help mb-4">Map up to 10 currently unassigned faculty mentors in the coordinator’s own department.</p>{isLoading ? <p className="text-sm text-slate-500">Loading faculty mapping…</p> : error ? <p className="text-sm text-red-700">{error.message}</p> : !coordinators.length ? <p className="text-sm text-amber-700">Add a Faculty Coordinator first.</p> : <><Label>Faculty Coordinator</Label><Select value={coordinatorId} onChange={(event) => { setCoordinatorId(event.target.value); setFacultyIds([]); setFacultySearch(''); }}><option value="">Choose a Faculty Coordinator</option>{coordinators.map((coordinator) => <option key={coordinator.id} value={coordinator.id}>{coordinator.full_name} — {coordinator.department?.code ?? 'No department'} ({coordinator.assigned_faculty.length}/10)</option>)}</Select>{selectedCoordinator && <div className="mt-4"><div className="flex items-center justify-between"><p className="text-sm font-bold text-slate-900">Unassigned faculty in {selectedCoordinator.department?.name}</p><Badge status="pending">{selectedCoordinator.assigned_faculty.length}/10 mapped</Badge></div>{availableFaculty.length && capacity > 0 ? <><div className="mt-3 flex flex-wrap items-end justify-between gap-3"><div className="min-w-56 flex-1"><Label>Search faculty</Label><Input className="mt-1" value={facultySearch} onChange={(event) => setFacultySearch(event.target.value)} placeholder="Name or email" /></div><div className="flex gap-3 text-sm font-bold"><button type="button" className="text-indigo-700 hover:underline disabled:text-slate-400" onClick={selectAllVisible} disabled={!filteredFaculty.length || facultyIds.length >= capacity}>Select all</button><button type="button" className="text-indigo-700 hover:underline disabled:text-slate-400" onClick={() => setFacultyIds([])} disabled={!facultyIds.length}>Clear</button></div></div><p className="mt-2 text-xs text-slate-500">{filteredFaculty.length} matching faculty · select up to {capacity} more.</p><div className="mt-2 max-h-48 space-y-2 overflow-y-auto rounded-lg border border-slate-200 p-3">{filteredFaculty.length ? filteredFaculty.map((faculty) => <label key={faculty.id} className="flex cursor-pointer items-center gap-2 text-sm text-slate-800"><input type="checkbox" checked={facultyIds.includes(faculty.id)} onChange={() => toggleFaculty(faculty.id)} disabled={!facultyIds.includes(faculty.id) && facultyIds.length >= capacity} /><span>{faculty.full_name}</span><span className="text-xs text-slate-500">{faculty.email}</span></label>) : <p className="py-2 text-sm text-slate-500">No unassigned faculty match this search.</p>}</div></> : <p className="mt-2 text-sm text-slate-500">{capacity ? 'No unassigned faculty mentors are available in this department.' : 'This coordinator already has the maximum 10 faculty mentors.'}</p>}<Button type="button" className="mt-3" onClick={() => mapFaculty.mutate()} disabled={!facultyIds.length || mapFaculty.isPending}>{mapFaculty.isPending ? 'Mapping…' : `Map selected faculty (${facultyIds.length})`}</Button>{selectedCoordinator.assigned_faculty.length > 0 && <div className="mt-5 border-t border-slate-100 pt-4"><p className="text-sm font-bold text-slate-900">Currently mapped faculty</p><ul className="mt-2 space-y-2">{selectedCoordinator.assigned_faculty.map((faculty) => <li key={faculty.id} className="flex items-center justify-between gap-2 rounded-lg bg-slate-50 px-3 py-2 text-sm"><span>{faculty.full_name}</span><button type="button" className="font-bold text-red-700 hover:underline" onClick={() => unmapFaculty.mutate(faculty.id)} disabled={unmapFaculty.isPending}>Unmap</button></li>)}</ul></div>}</div>}{message && <p className={`mt-3 text-sm ${mapFaculty.isError || unmapFaculty.isError ? 'text-red-700' : 'text-emerald-700'}`}>{message}</p>}</>}</Card>;
}

export default function UserManagement() {
  const queryClient = useQueryClient();
  const [activeTab, setActiveTab] = useState('organisation');
  const [method, setMethod] = useState('individual');
  const { data: schools = [], isLoading: schoolsLoading } = useQuery({ queryKey: ['schools'], queryFn: () => api('/schools') });
  const { data: departments = [] } = useQuery({ queryKey: ['departments'], queryFn: () => api('/departments') });
  const { data: users = [] } = useQuery({ queryKey: ['portal-users'], queryFn: () => api('/admin/users') });
  const refresh = () => { queryClient.invalidateQueries({ queryKey: ['schools'] }); queryClient.invalidateQueries({ queryKey: ['departments'] }); queryClient.invalidateQueries({ queryKey: ['portal-users'] }); };
  const tabs = [['organisation', 'Organisation setup'], ['people', 'Add people'], ['faculty-mapping', 'Map Faculty Coordinators'], ['access', 'Coordinator access']];
  return <div className="max-w-5xl"><PageHeader eyebrow="Administration" title="User Management" description="Set up your organisation, add portal accounts, and control CRCS Coordinator access." />
    <div className="portal-tabbar">{tabs.map(([id, label]) => <button key={id} type="button" onClick={() => setActiveTab(id)} className={`portal-tab ${activeTab === id ? 'portal-tab-active' : 'border-transparent'}`}>{label}</button>)}</div>
    {activeTab === 'organisation' && <section><StepTitle number="1" title="Set up your organisation" description="Create these only if they are not already listed below. CSE students automatically resolve to their CSE HOD and parent school in the directory." />{schoolsLoading ? <p className="text-sm text-slate-500">Loading organisation details…</p> : <div className="grid gap-4 xl:grid-cols-2"><SchoolForm schools={schools} onCreated={refresh} /><DepartmentForm schools={schools} departments={departments} onCreated={refresh} /></div>}</section>}
    {activeTab === 'people' && <section><StepTitle number="2" title="Add people" description="Choose the fastest way to add accounts. You can use both methods at any time." /><div className="mb-5 grid gap-3 sm:grid-cols-2"><button type="button" onClick={() => setMethod('individual')} className={`rounded-xl border p-4 text-left transition ${method === 'individual' ? 'border-indigo-500 bg-indigo-50 ring-2 ring-indigo-100' : 'border-slate-200 bg-white hover:border-indigo-200'}`}><p className="font-bold">Add one person</p><p className="mt-1 text-sm text-slate-600">For one student, mentor, or administrator.</p></button><button type="button" onClick={() => setMethod('bulk')} className={`rounded-xl border p-4 text-left transition ${method === 'bulk' ? 'border-indigo-500 bg-indigo-50 ring-2 ring-indigo-100' : 'border-slate-200 bg-white hover:border-indigo-200'}`}><p className="font-bold">Import a spreadsheet</p><p className="mt-1 text-sm text-slate-600">For a class, department, or large group.</p></button></div>{method === 'individual' ? <IndividualOnboard schools={schools} departments={departments} onDone={refresh} /> : <BulkOnboard departments={departments} onDone={refresh} />}</section>}
    {activeTab === 'faculty-mapping' && <section><StepTitle number="3" title="Map Faculty Coordinators" description="A Faculty Coordinator automatically belongs to the HOD of the same department. Use this page only to map that coordinator to their faculty mentors." /><FacultyCoordinatorMapping /></section>}
    {activeTab === 'access' && <section><div className="mb-4"><h2 className="section-title">CRCS coordinator access</h2><p className="mt-1 text-sm text-slate-600">Choose what each CRCS Coordinator can view and manage.</p></div><CRCSPermissionsConfig embedded /></section>}
  </div>;
}
